using Scriban;

namespace ERDesigner.Generator;

internal sealed class ScribanCSharpRenderer
{
    private const string TemplateText = """
        // <auto-generated />
        #nullable enable

        {{ for u in usings }}using {{ u }};
        {{ end }}
        namespace {{ namespace_name }};

        {{~ if emit_nav_ref_attr ~}}
        /// <summary>Entity navigation に参照カラム情報を付加する独自属性です。</summary>
        [AttributeUsage(AttributeTargets.Property, AllowMultiple = false)]
        public sealed class NavigationReferenceAttribute : Attribute
        {
        	public string PrincipalColumn { get; }

        	public string DependentColumn { get; }

        	public NavigationReferenceAttribute(string principalColumn, string dependentColumn)
        	{
        		PrincipalColumn = principalColumn;
        		DependentColumn = dependentColumn;
        	}
        }
        {{ end }}
        {{~ for item in entity_classes ~}}
        {{ if include_data_annotations }}[Table("{{ item.table_name }}")]
        {{ end }}public partial class {{ item.class_name }}
        {
        {{ for property in item.properties }}{{ if include_data_annotations && property.is_primary_key }}    [Key]
        {{ end }}{{ if include_data_annotations }}    [Column("{{ property.column_name }}")]
        {{ end }}{{ if include_data_annotations && !property.is_nullable && property.is_reference_type }}    [Required]
        {{ end }}{{ if include_data_annotations && property.max_length }}    [MaxLength({{ property.max_length }})]
        {{ end }}    public {{ property.type_name }} {{ property.property_name }} { get; set; }{{ property.initializer }}

        {{ end }}{{ for navigation in item.navigations }}{{ if include_json_ignore_on_parent_navigation && navigation.is_parent_reference }}    [JsonIgnore]
        {{ end }}    [NavigationReference("{{ navigation.principal_column_name }}", "{{ navigation.dependent_column_name }}")]
        	public {{ navigation.display_type_name }} {{ navigation.property_name }} { get; set; }{{ navigation.initializer }}

        {{ end }}}
        {{~ end ~}}

        {{~ for item in edit_model_classes ~}}
        public partial class {{ item.class_name }} : INotifyPropertyChanged, INotifyDataErrorInfo
        {
        	// ---- INotifyPropertyChanged ----
        	public event PropertyChangedEventHandler? PropertyChanged;

        	private void OnPropertyChanged(string propertyName) =>
        		PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));

        	// ---- INotifyDataErrorInfo ----
        	private readonly Dictionary<string, List<string>> _errors = new();

        	public bool HasErrors => _errors.Count > 0;

        	public event EventHandler<DataErrorsChangedEventArgs>? ErrorsChanged;

        	public System.Collections.IEnumerable GetErrors(string? propertyName)
        	{
        		if (string.IsNullOrEmpty(propertyName))
        		{
        			return _errors.Values.SelectMany(e => e);
        		}

        		return _errors.TryGetValue(propertyName, out var list) ? list : Enumerable.Empty<string>();
        	}

        	private void SetError(string propertyName, string? error)
        	{
        		if (error is null)
        		{
        			if (_errors.Remove(propertyName))
        			{
        				ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
        			}

        			return;
        		}

        		_errors[propertyName] = [error];
        		ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
        	}

        	// ---- リバート中フラグ (無限ループ防止) ----
        	private bool _isReverting;

        	// ---- プロパティ ----
        {{ for p in item.properties }}{{ if p.field_initializer != "" }}    private {{ p.type_name }} {{ p.field_name }} = {{ p.field_initializer }};
        {{ else }}    private {{ p.type_name }} {{ p.field_name }};
        {{ end }}    private string {{ p.binding_field_name }} = {{ p.binding_field_initializer }};
        	private string? {{ p.error_field_name }};

        	/// <summary>{{ p.property_name }} 確定値プロパティです。</summary>
        	public {{ p.type_name }} {{ p.property_name }}
        	{
        		get => {{ p.field_name }};
        		private set
        		{
        			if (!Equals({{ p.field_name }}, value))
        			{
        				{{ p.field_name }} = value;
        				OnPropertyChanged(nameof({{ p.property_name }}));
        			}
        		}
        	}

        	/// <summary>{{ p.binding_property_name }} バインディング用プロパティです。</summary>
        	public string {{ p.binding_property_name }}
        	{
        		get => {{ p.binding_field_name }};
        		set
        		{
        			if ({{ p.binding_field_name }} == value)
        			{
        				return;
        			}

        			{{ p.binding_field_name }} = value;
        			OnPropertyChanged(nameof({{ p.binding_property_name }}));

        			if (!_isReverting)
        			{
        {{ if p.needs_parse }}                if ({{ p.parse_type_name }}.TryParse(value, out var parsed))
        				{
        					{{ p.property_name }} = parsed;
        					{{ p.error_field_name }} = null;
        					SetError(nameof({{ p.binding_property_name }}), null);
        				}
        				else
        				{
        					{{ p.error_field_name }} = $"'{value}' は {{ p.type_name }} に変換できません。";
        					SetError(nameof({{ p.binding_property_name }}), {{ p.error_field_name }});
        				}
        {{ else if p.is_nullable }}                if (string.IsNullOrEmpty(value))
        				{
        					{{ p.property_name }} = null;
        					{{ p.error_field_name }} = null;
        					SetError(nameof({{ p.binding_property_name }}), null);
        				}
        				else
        				{
        					{{ p.property_name }} = value;
        					{{ p.error_field_name }} = null;
        					SetError(nameof({{ p.binding_property_name }}), null);
        				}
        {{ else }}                {{ p.property_name }} = value;
        				{{ p.error_field_name }} = null;
        				SetError(nameof({{ p.binding_property_name }}), null);
        {{ end }}            }
        		}
        	}

        {{ end }}    // ---- navigation ----
        {{ for navigation in item.navigations }}    public {{ navigation.display_type_name }} {{ navigation.property_name }} { get; set; }{{ navigation.initializer }}

        {{ end }}
        	/// <summary>確定値をバインディング用プロパティに書き戻し、エラー情報をクリアします。</summary>
        	public void RevertInput()
        	{
        		_isReverting = true;

        		try
        		{
        {{ for p in item.properties }}            {{ p.binding_property_name }} = {{ p.property_name }}?.ToString() ?? string.Empty;
        			{{ p.error_field_name }} = null;
        			SetError(nameof({{ p.binding_property_name }}), null);
        {{ end }}        }
        		finally
        		{
        			_isReverting = false;
        		}
        	}
        }
        {{~ end ~}}

        {{~ for mapper in mapper_classes ~}}
        public sealed class {{ mapper.class_name }}
        {
        public {{ mapper.edit_model_class_name }} CommitToEditModel({{ mapper.entity_class_name }} entity)
        {
            var editModel = new {{ mapper.edit_model_class_name }}();
            LoadFrom(entity, editModel);
            return editModel;
        }

        public void CommitToEntity({{ mapper.edit_model_class_name }} editModel, {{ mapper.entity_class_name }} entity)
        {
        {{ for prop in mapper.scalar_properties }}        entity.{{ prop.property_name }} = editModel.{{ prop.property_name }};
        {{ end }}    }

            private static void LoadFrom({{ mapper.entity_class_name }} entity, {{ mapper.edit_model_class_name }} editModel)
        {
            editModel.RevertInput();
        {{ for prop in mapper.scalar_properties }}        editModel.{{ prop.binding_property_name }} = entity.{{ prop.property_name }}?.ToString() ?? string.Empty;
        {{ end }}    }
        }
        {{~ end ~}}
        """;

    public string Render(CSharpGenerationModel model, CodeGenerationOptions options)
    {
        var template = Template.Parse(TemplateText);
        if (template.HasErrors)
        {
            var message = string.Join(Environment.NewLine, template.Messages.Select(m => m.ToString()));
            throw new InvalidOperationException($"C# 生成テンプレートの解析に失敗しました。{Environment.NewLine}{message}");
        }

        var emitNavRefAttr = options.GenerateEntityClasses && model.EntityClasses.Any(c => c.Navigations.Count > 0);

        var scriptObject = new Scriban.Runtime.ScriptObject
        {
            ["namespace_name"] = model.NamespaceName,
            ["usings"] = model.Usings,
            ["entity_classes"] = model.EntityClasses,
            ["edit_model_classes"] = model.EditModelClasses,
            ["mapper_classes"] = model.MapperClasses,
            ["include_data_annotations"] = options.IncludeDataAnnotations,
            ["include_json_ignore_on_parent_navigation"] = options.IncludeJsonIgnoreOnParentNavigation,
            ["emit_nav_ref_attr"] = emitNavRefAttr,
        };

        var context = new TemplateContext();
        context.PushGlobal(scriptObject);
        return template.Render(context).ReplaceLineEndings(Environment.NewLine).TrimEnd() + Environment.NewLine;
    }
}
